import '../../src/styles/index.css';
import '../../src/styles/atelier.css';
import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';import GaleriPanel from '../../src/components/GaleriPanel.jsx';import ViridariumTemplate from '../../src/components/templates/viridarium/ViridariumTemplate.jsx';import {UIProvider} from '../../src/context/UIContext.jsx';import {api} from '../../src/api/client.js';import {mergePreviewOverride} from '../../src/utils/mergePreviewOverride.js';
const initial={id:'gallery-qa',themeId:'garden-canvas',themeSettings:{galleryLayout:'collage',characterSettings:{mode:'default'}},coupleProfile:{brideName:'A',groomName:'B'},invitationFeatures:{galleryEnabled:true},galleryMedia:[{id:'one',type:'photo',url:'/assets/landing-canvas/garden.webp',order:0},{id:'two',type:'photo',url:'/assets/landing-canvas/couple.webp',order:1},{id:'three',type:'photo',url:'/assets/landing-canvas/twilight.webp',order:2},{id:'four',type:'photo',url:'/assets/landing-canvas/rosewalk.webp',order:3},{id:'five',type:'photo',url:'/assets/landing-canvas/garden.webp',order:4},{id:'six',type:'video',url:'/assets/gallery/dummy-gallery-video.mp4',order:5},{id:'seven',type:'photo',url:'/assets/landing-canvas/rosewalk.webp',order:6},{id:'eight',type:'photo',url:'/assets/landing-canvas/twilight.webp',order:7},{id:'nine',type:'photo',url:'/assets/landing-canvas/garden.webp',order:8},{id:'ten',type:'photo',url:'/assets/landing-canvas/rosewalk.webp',order:9}]};
api.get=async()=>({data:{media:initial.galleryMedia,maxGallery:10}});api.patch=async(url,payload)=>({data:{themeSettings:{...initial.themeSettings,...payload}}});
function App(){const [inv,setInv]=useState(initial),[patch,setPatch]=useState(null);const wrap=useRef(null);function open(){const w=wrap.current.querySelector('iframe').contentWindow;w.document.querySelector('#open').click();setTimeout(()=>w.document.querySelector('.section-dot[data-scene="galeri"]').click(),4000)}return <UIProvider><div className="atelier-app" style={{display:'grid',gridTemplateColumns:'420px 390px',gap:30}}><div className="panel" style={{padding:20,background:'#faf8ef'}}><GaleriPanel invitation={inv} onUpdated={setInv} onLivePreview={setPatch}/></div><div><button onClick={()=>setInv({...initial,galleryMedia:Array.from({length:40},(_,i)=>({...initial.galleryMedia[i%6],id:`media-${i}`,order:i}))})}>Uji 40 media</button><button onClick={()=>setInv(initial)}>Uji 6 media</button><button onClick={open}>Buka galeri di preview</button><div ref={wrap} style={{width:390,height:844,position:'relative'}}><ViridariumTemplate invitation={mergePreviewOverride(inv,patch)}/></div></div></div></UIProvider>}
createRoot(document.getElementById('root')).render(<App/>);
